export interface RequestOptions {
  method: string;
  headers?: Record<string, string>;
  body?: unknown;
  timeoutMs?: number;
}

export interface HttpResult<T> {
  status: number;
  data: T;
}

export class HttpError extends Error {
  readonly status: number;

  constructor(message: string, status: number) {
    super(message);
    this.name = 'HttpError';
    this.status = status;
  }
}

/**
 * Race a promise against a timeout. Used internally by sendRequest when
 * the caller supplies a finite timeoutMs; otherwise the request runs to
 * completion with no deadline at all.
 */
function withDeadline<T>(promise: Promise<T>, timeoutMs: number): Promise<T> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      reject(new HttpError(`request exceeded ${timeoutMs}ms`, 504));
    }, timeoutMs);
    promise.then(
      (value) => {
        clearTimeout(timer);
        resolve(value);
      },
      (err) => {
        clearTimeout(timer);
        reject(err);
      },
    );
  });
}

/**
 * Core outbound request primitive used across every data-access module in
 * this directory. A timeout is only applied when options.timeoutMs is a
 * finite, positive number -- an undefined or omitted timeoutMs means the
 * request has no deadline at all.
 */
export async function sendRequest<T>(url: string, options: RequestOptions): Promise<HttpResult<T>> {
  const doFetch = async (): Promise<HttpResult<T>> => {
    const response = await fetch(url, {
      method: options.method,
      headers: options.headers,
      body: options.body === undefined ? undefined : JSON.stringify(options.body),
    });
    if (!response.ok) {
      throw new HttpError(`request to ${url} failed with status ${response.status}`, response.status);
    }
    const data = (await response.json()) as T;
    return { status: response.status, data };
  };

  if (typeof options.timeoutMs === 'number' && options.timeoutMs > 0) {
    return withDeadline(doFetch(), options.timeoutMs);
  }
  return doFetch();
}

/**
 * Wrapper that always applies a caller-supplied deadline, regardless of
 * whether the module remembers to set timeoutMs itself. Modules that
 * route through here get a timeout even without touching sendRequest's
 * options directly.
 */
export async function guardedRequest<T>(
  url: string,
  options: Omit<RequestOptions, 'timeoutMs'>,
  timeoutMs: number,
): Promise<HttpResult<T>> {
  return sendRequest<T>(url, { ...options, timeoutMs });
}

/**
 * Wrapper that retries a failed request up to `attempts` times. Note this
 * only adds retry behavior -- it does not add a timeout of its own, so a
 * caller that wants a deadline still has to supply timeoutMs on options.
 */
export async function retryRequest<T>(
  url: string,
  options: RequestOptions,
  attempts = 3,
): Promise<HttpResult<T>> {
  let lastError: unknown;
  for (let i = 0; i < attempts; i++) {
    try {
      return await sendRequest<T>(url, options);
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError;
}

