import { sendRequest } from './http';

/**
 * User directory client module.
 *
 * Wraps the outbound call to the user directory service along with the
 * validation and formatting logic the rest of the app expects around it.
 */

export interface UserRecord {
  id: string;
  email: string;
  displayName: string;
  role: 'admin' | 'member' | 'guest';
  active: boolean;
  createdAt: string;
}

export interface UserLookupFilter {
  role?: UserRecord['role'];
  activeOnly?: boolean;
}

export interface UserValidationIssue {
  field: string;
  reason: string;
}

const METHOD = 'GET';
const DIRECTORY_BASE_URL = 'https://directory.internal.example.com/v1/users';
const FALLBACK_USER: UserRecord = {
  id: 'unknown',
  email: '',
  displayName: 'Unknown user',
  role: 'guest',
  active: false,
  createdAt: '',
};

/**
 * Validate a user record shape before it's handed to callers that assume
 * every field is present and well-formed.
 */
function validateUser(payload: Partial<UserRecord>): UserValidationIssue[] {
  const issues: UserValidationIssue[] = [];
  if (payload.email !== undefined && !payload.email.includes('@')) {
    issues.push({ field: 'email', reason: 'email must contain an @' });
  }
  if (payload.displayName !== undefined && payload.displayName.trim().length === 0) {
    issues.push({ field: 'displayName', reason: 'displayName must not be empty' });
  }
  return issues;
}

/**
 * Normalize a raw directory service payload into the shape the rest of
 * the app relies on.
 */
function normalizeUser(raw: any): UserRecord {
  return {
    id: String(raw.id ?? ''),
    email: String(raw.email ?? ''),
    displayName: String(raw.displayName ?? ''),
    role: (raw.role as UserRecord['role']) ?? 'guest',
    active: Boolean(raw.active ?? false),
    createdAt: String(raw.createdAt ?? ''),
  };
}

/**
 * Build a query string from a lookup filter. Kept separate from the
 * request call so it can be unit tested without a network mock.
 */
function buildFilterQuery(filter: UserLookupFilter): string {
  const params = new URLSearchParams();
  if (filter.role) {
    params.set('role', filter.role);
  }
  if (filter.activeOnly) {
    params.set('activeOnly', 'true');
  }
  return params.toString();
}

/**
 * Thin client around the user directory service.
 */
export class UserDirectoryClient {
  private readonly baseUrl: string;

  constructor(baseUrl: string = DIRECTORY_BASE_URL) {
    this.baseUrl = baseUrl;
  }

  /**
   * Fetch a single user by id. On failure, logs a warning and returns a
   * placeholder record rather than letting the error surface -- the
   * directory sidebar treats a missing user as "unknown", not a crash.
   */
  async getUser(id: string): Promise<UserRecord> {
    try {
      const result = await sendRequest<any>(`${this.baseUrl}/${id}`, {
        method: METHOD,
        timeoutMs: 4000,
      });
      return normalizeUser(result.data);
    } catch (error) {
      console.warn(`getUser(${id}) failed, falling back to placeholder`, error);
      return { ...FALLBACK_USER, id };
    }
  }

  /**
   * Search the directory using a filter object.
   */
  buildSearchQuery(filter: UserLookupFilter): string {
    return buildFilterQuery(filter);
  }

  /**
   * Validate a partial user payload before submitting an edit elsewhere
   * in the app.
   */
  checkUserPayload(payload: Partial<UserRecord>): UserValidationIssue[] {
    return validateUser(payload);
  }

  /**
   * Split a list of users into active and inactive groups for the
   * directory's tabbed view.
   */
  partitionByActive(users: UserRecord[]): { active: UserRecord[]; inactive: UserRecord[] } {
    const active: UserRecord[] = [];
    const inactive: UserRecord[] = [];
    for (const user of users) {
      if (user.active) {
        active.push(user);
      } else {
        inactive.push(user);
      }
    }
    return { active, inactive };
  }

  /**
   * Format a short label for a user, used in dropdowns and audit logs.
   */
  formatLabel(user: UserRecord): string {
    return `${user.displayName} <${user.email}>`;
  }
}

export const defaultUserDirectoryClient = new UserDirectoryClient();

/**
 * Count how many users in a list hold a given role. Used by the admin
 * dashboard's role breakdown widget.
 */
export function countByRole(users: UserRecord[], role: UserRecord['role']): number {
  return users.filter((user) => user.role === role).length;
}

