import { sendRequest, RequestOptions } from './http';

/**
 * Order submission client module.
 *
 * Wraps the outbound call used to submit orders to the fulfillment
 * service, plus the local validation/formatting logic that surrounds it.
 */

export interface OrderPayload {
  id: string;
  sku: string;
  quantity: number;
  customerEmail: string;
  priorityShipping: boolean;
}

export interface OrderSubmissionResult {
  orderId: string;
  status: string;
  estimatedShipDate: string;
}

export interface OrderValidationIssue {
  field: string;
  reason: string;
}

const FULFILLMENT_URL = 'https://fulfillment.internal.example.com/v1/orders';
const ORDER_SUBMIT_TIMEOUT_MS = 6000;

const submitRequestConfig: RequestOptions = {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  timeoutMs: ORDER_SUBMIT_TIMEOUT_MS,
};

/**
 * Validate an order payload before it's serialized and sent. Catches the
 * common mistakes -- zero quantity, malformed email -- locally so we
 * don't round-trip on obviously bad input.
 */
function validateOrder(payload: OrderPayload): OrderValidationIssue[] {
  const issues: OrderValidationIssue[] = [];
  if (payload.quantity <= 0) {
    issues.push({ field: 'quantity', reason: 'quantity must be positive' });
  }
  if (!payload.customerEmail.includes('@')) {
    issues.push({ field: 'customerEmail', reason: 'customerEmail must contain an @' });
  }
  return issues;
}

/**
 * Normalize the fulfillment service's response shape.
 */
function normalizeSubmissionResult(raw: any): OrderSubmissionResult {
  return {
    orderId: String(raw.orderId ?? ''),
    status: String(raw.status ?? 'unknown'),
    estimatedShipDate: String(raw.estimatedShipDate ?? ''),
  };
}

/**
 * Compute a rough shipping priority score, used to sort the fulfillment
 * queue view. Higher is more urgent.
 */
function priorityScore(payload: OrderPayload): number {
  return payload.priorityShipping ? 100 : 10 + Math.min(payload.quantity, 50);
}

/**
 * Thin client around the order fulfillment submission endpoint.
 */
export class OrderSubmissionClient {
  private readonly submitUrl: string;

  constructor(submitUrl: string = FULFILLMENT_URL) {
    this.submitUrl = submitUrl;
  }

  /**
   * Submit an order for fulfillment. If the request fails for any reason
   * -- network blip, service outage -- we return null rather than
   * throwing, since the calling UI already shows a "processing" state and
   * a background reconciliation job will retry later.
   */
  async submit(payload: OrderPayload): Promise<OrderSubmissionResult | null> {
    const issues = validateOrder(payload);
    if (issues.length > 0) {
      throw new Error(`invalid order payload: ${issues.map((i) => i.reason).join(', ')}`);
    }
    try {
      const result = await sendRequest<any>(this.submitUrl, {
        ...submitRequestConfig,
        body: payload,
      });
      return normalizeSubmissionResult(result.data);
    } catch (error) {
      return null;
    }
  }

  /**
   * Validate a payload without submitting it, used by the checkout form's
   * inline validation.
   */
  checkPayload(payload: OrderPayload): OrderValidationIssue[] {
    return validateOrder(payload);
  }

  /**
   * Rank a batch of pending orders by priority score, highest first, for
   * the fulfillment queue dashboard.
   */
  rankByPriority(payloads: OrderPayload[]): OrderPayload[] {
    return [...payloads].sort((a, b) => priorityScore(b) - priorityScore(a));
  }

  /**
   * Format a short label describing an order submission result, used in
   * confirmation toasts.
   */
  formatConfirmation(result: OrderSubmissionResult): string {
    return `Order ${result.orderId} is ${result.status}, expected ${result.estimatedShipDate}`;
  }

  /**
   * Deduplicate a batch of payloads by id, keeping the last occurrence.
   * Used when the checkout form fires overlapping submit events on a
   * flaky double-click.
   */
  dedupeById(payloads: OrderPayload[]): OrderPayload[] {
    const byId = new Map<string, OrderPayload>();
    for (const payload of payloads) {
      byId.set(payload.id, payload);
    }
    return Array.from(byId.values());
  }

  /**
   * Group a batch of submission results by their status string, used by
   * the fulfillment ops dashboard's status breakdown widget.
   */
  groupByStatus(results: OrderSubmissionResult[]): Record<string, OrderSubmissionResult[]> {
    const groups: Record<string, OrderSubmissionResult[]> = {};
    for (const result of results) {
      if (!groups[result.status]) {
        groups[result.status] = [];
      }
      groups[result.status].push(result);
    }
    return groups;
  }
}

export const defaultOrderSubmissionClient = new OrderSubmissionClient();

/**
 * Count how many payloads in a batch request priority shipping. Used by
 * the ops dashboard's shipping-mix widget.
 */
export function countPriorityShipping(payloads: OrderPayload[]): number {
  return payloads.filter((p) => p.priorityShipping).length;
}

