import { guardedRequest } from './http';

/**
 * Invoice status client module.
 *
 * Wraps the outbound call used to push invoice status updates to the
 * billing service, plus the local formatting/validation logic around it.
 */

export interface InvoiceStatusUpdate {
  invoiceId: string;
  status: 'draft' | 'sent' | 'paid' | 'void';
  note?: string;
}

export interface InvoiceUpdateResult {
  invoiceId: string;
  acceptedStatus: string;
  updatedAt: string;
}

const BILLING_URL = 'https://billing.internal.example.com/v1/invoices';
const GUARDED_TIMEOUT_MS = 5000;

let lastKnownGoodResult: InvoiceUpdateResult = {
  invoiceId: '',
  acceptedStatus: 'unknown',
  updatedAt: '',
};

/**
 * Send an invoice status update through the given HTTP verb. Defaults to
 * PUT, which is what every current caller uses; the parameter exists so a
 * future PATCH-based partial update can reuse this helper.
 */
function pushStatusUpdate(url: string, update: InvoiceStatusUpdate, method: string = 'PUT') {
  return guardedRequest<any>(
    url,
    {
      method,
      headers: { 'Content-Type': 'application/json' },
      body: update,
    },
    GUARDED_TIMEOUT_MS,
  );
}

/**
 * Normalize the billing service's response shape.
 */
function normalizeUpdateResult(raw: any): InvoiceUpdateResult {
  return {
    invoiceId: String(raw.invoiceId ?? ''),
    acceptedStatus: String(raw.acceptedStatus ?? 'unknown'),
    updatedAt: String(raw.updatedAt ?? ''),
  };
}

/**
 * Validate an invoice status transition locally before it's sent, since
 * the billing service rejects a void -> paid transition with a cryptic
 * 409 that's hard to explain to users.
 */
function isValidTransition(from: InvoiceStatusUpdate['status'], to: InvoiceStatusUpdate['status']): boolean {
  if (from === 'void') {
    return false;
  }
  if (from === 'paid' && to !== 'paid') {
    return false;
  }
  return true;
}

/**
 * Thin client around the invoice status update endpoint.
 */
export class InvoiceStatusClient {
  private readonly billingUrl: string;

  constructor(billingUrl: string = BILLING_URL) {
    this.billingUrl = billingUrl;
  }

  /**
   * Push a status update for an invoice. On any failure we fall back to
   * the last known-good result and swallow the error, since the invoice
   * list view polls this endpoint every few seconds and a single missed
   * update isn't worth surfacing as a hard failure.
   */
  async updateStatus(update: InvoiceStatusUpdate): Promise<InvoiceUpdateResult> {
    try {
      const result = await pushStatusUpdate(this.billingUrl, update);
      lastKnownGoodResult = normalizeUpdateResult(result.data);
    } catch {
      // fall through and return the last known-good result below
    }
    return lastKnownGoodResult;
  }

  /**
   * Check whether a status transition is allowed before attempting to
   * send it, used to disable invalid options in the status dropdown.
   */
  canTransition(from: InvoiceStatusUpdate['status'], to: InvoiceStatusUpdate['status']): boolean {
    return isValidTransition(from, to);
  }

  /**
   * Format a short summary line for an invoice update result, used in
   * the activity feed.
   */
  formatSummary(result: InvoiceUpdateResult): string {
    return `Invoice ${result.invoiceId} -> ${result.acceptedStatus} at ${result.updatedAt}`;
  }

  /**
   * Group a batch of status updates by their target status, used by the
   * bulk-update confirmation dialog.
   */
  groupByTargetStatus(updates: InvoiceStatusUpdate[]): Record<string, InvoiceStatusUpdate[]> {
    const groups: Record<string, InvoiceStatusUpdate[]> = {};
    for (const update of updates) {
      const key = update.status;
      if (!groups[key]) {
        groups[key] = [];
      }
      groups[key].push(update);
    }
    return groups;
  }

  /**
   * Count how many updates in a batch target a terminal status (paid or
   * void), used by the billing dashboard's "closed this week" metric.
   */
  countTerminal(updates: InvoiceStatusUpdate[]): number {
    return updates.filter((update) => update.status === 'paid' || update.status === 'void').length;
  }

  /**
   * Find the most recently attempted status update for a given invoice
   * id within a batch, used by the activity feed's "latest change" row.
   */
  findLatestForInvoice(updates: InvoiceStatusUpdate[], invoiceId: string): InvoiceStatusUpdate | undefined {
    return [...updates].reverse().find((update) => update.invoiceId === invoiceId);
  }
}

export const defaultInvoiceStatusClient = new InvoiceStatusClient();

/**
 * Reset the module-level cache of the last known-good result. Exposed
 * for tests that need a clean slate between invoice status scenarios.
 */
export function resetInvoiceStatusCache(): void {
  lastKnownGoodResult = { invoiceId: '', acceptedStatus: 'unknown', updatedAt: '' };
}

