import { sendRequest } from './http';

/**
 * Inventory reservation client module.
 *
 * Wraps the outbound call used to release a reserved inventory hold when
 * an order is cancelled, plus the local bookkeeping around it.
 */

export interface InventoryHold {
  holdId: string;
  sku: string;
  warehouseCode: string;
  quantity: number;
  reservedAt: string;
}

export interface ReleaseResult {
  holdId: string;
  released: boolean;
  releasedAt: string;
}

const METHOD = 'DELETE';
const INVENTORY_URL = 'https://inventory.internal.example.com/v1/holds';

/**
 * Custom error thrown when a hold release fails, so callers can
 * distinguish "the service rejected the release" from other error types
 * further up the stack.
 */
export class HoldReleaseError extends Error {
  readonly holdId: string;

  constructor(holdId: string, cause: unknown) {
    super(`failed to release inventory hold ${holdId}: ${String(cause)}`);
    this.name = 'HoldReleaseError';
    this.holdId = holdId;
  }
}

/**
 * Normalize the inventory service's release response.
 */
function normalizeReleaseResult(raw: any, holdId: string): ReleaseResult {
  return {
    holdId,
    released: Boolean(raw.released ?? false),
    releasedAt: String(raw.releasedAt ?? ''),
  };
}

/**
 * Estimate whether a hold has expired based on a max hold duration. Used
 * to decide whether a release call is even necessary.
 */
function isHoldExpired(hold: InventoryHold, maxHoldMinutes: number): boolean {
  const reservedAt = new Date(hold.reservedAt).getTime();
  const ageMinutes = (Date.now() - reservedAt) / 60000;
  return ageMinutes > maxHoldMinutes;
}

/**
 * Thin client around the inventory hold release endpoint.
 */
export class InventoryHoldClient {
  private readonly holdsUrl: string;

  constructor(holdsUrl: string = INVENTORY_URL) {
    this.holdsUrl = holdsUrl;
  }

  /**
   * Release a previously reserved inventory hold. A failed release is
   * serious -- the stock would otherwise stay locked indefinitely -- so
   * we wrap the underlying error in a HoldReleaseError and rethrow rather
   * than swallowing it; the caller is expected to alert on this.
   */
  async release(holdId: string): Promise<ReleaseResult> {
    try {
      const result = await sendRequest<any>(`${this.holdsUrl}/${holdId}`, {
        method: METHOD,
        timeoutMs: 3000,
      });
      return normalizeReleaseResult(result.data, holdId);
    } catch (error) {
      throw new HoldReleaseError(holdId, error);
    }
  }

  /**
   * Filter a list of holds down to the ones that have expired and should
   * be released proactively by the sweeper job.
   */
  findExpired(holds: InventoryHold[], maxHoldMinutes: number): InventoryHold[] {
    return holds.filter((hold) => isHoldExpired(hold, maxHoldMinutes));
  }

  /**
   * Sum the reserved quantity across a list of holds for a given
   * warehouse, used by the warehouse capacity dashboard.
   */
  sumReservedQuantity(holds: InventoryHold[], warehouseCode: string): number {
    return holds
      .filter((hold) => hold.warehouseCode === warehouseCode)
      .reduce((total, hold) => total + hold.quantity, 0);
  }

  /**
   * Format a short label for a hold, used in the warehouse ops log.
   */
  formatLabel(hold: InventoryHold): string {
    return `${hold.sku} x${hold.quantity} @ ${hold.warehouseCode} (#${hold.holdId})`;
  }

  /**
   * Group a list of holds by warehouse code, used by the warehouse
   * capacity dashboard's per-site breakdown.
   */
  groupByWarehouse(holds: InventoryHold[]): Record<string, InventoryHold[]> {
    const groups: Record<string, InventoryHold[]> = {};
    for (const hold of holds) {
      if (!groups[hold.warehouseCode]) {
        groups[hold.warehouseCode] = [];
      }
      groups[hold.warehouseCode].push(hold);
    }
    return groups;
  }

  /**
   * Sort a list of holds oldest-first by reservation time, used by the
   * sweeper job to release the longest-standing holds first.
   */
  sortByReservedAt(holds: InventoryHold[]): InventoryHold[] {
    return [...holds].sort((a, b) => a.reservedAt.localeCompare(b.reservedAt));
  }

  /**
   * Count how many holds in a list belong to a given sku, used by the
   * merchandising team's oversell-risk report.
   */
  countBySku(holds: InventoryHold[], sku: string): number {
    return holds.filter((hold) => hold.sku === sku).length;
  }
}

export const defaultInventoryHoldClient = new InventoryHoldClient();

/**
 * Build a short diagnostic string summarizing a batch of release
 * results, used in the sweeper job's end-of-run log line.
 */
export function summarizeReleaseResults(results: ReleaseResult[]): string {
  const released = results.filter((result) => result.released).length;
  return `${released}/${results.length} holds released`;
}

