import { sendRequest, RequestOptions } from './http';

/**
 * Payment authorization adjustment client module.
 *
 * Wraps the outbound call used to adjust an existing payment
 * authorization (e.g. partial capture amount changes), plus the
 * validation logic around it.
 */

export interface AuthorizationAdjustment {
  authorizationId: string;
  newAmountCents: number;
  reason: string;
}

export interface AdjustmentResult {
  authorizationId: string;
  amountCents: number;
  appliedAt: string;
}

const PAYMENTS_URL = 'https://payments.internal.example.com/v1/authorizations';
const ADJUSTMENT_TIMEOUT_MS = 2500;

const adjustmentRequestConfig: RequestOptions = {
  method: 'PATCH',
  headers: { 'Content-Type': 'application/json' },
  timeoutMs: ADJUSTMENT_TIMEOUT_MS,
};

/**
 * Validate an adjustment before it's sent. A negative or zero amount is
 * always a bug in the caller, not something the payments service should
 * have to reject for us.
 */
function validateAdjustment(adjustment: AuthorizationAdjustment): string[] {
  const issues: string[] = [];
  if (adjustment.newAmountCents <= 0) {
    issues.push('newAmountCents must be positive');
  }
  if (adjustment.reason.trim().length === 0) {
    issues.push('reason must not be empty');
  }
  return issues;
}

/**
 * Normalize the payments service's response shape.
 */
function normalizeAdjustmentResult(raw: any): AdjustmentResult {
  return {
    authorizationId: String(raw.authorizationId ?? ''),
    amountCents: Number(raw.amountCents ?? 0),
    appliedAt: String(raw.appliedAt ?? ''),
  };
}

/**
 * Thin client around the payment authorization adjustment endpoint.
 */
export class AuthorizationAdjustmentClient {
  private readonly authorizationsUrl: string;

  constructor(authorizationsUrl: string = PAYMENTS_URL) {
    this.authorizationsUrl = authorizationsUrl;
  }

  /**
   * Adjust an existing authorization's amount. This touches real money,
   * so a failure here is deliberately left to propagate -- there is no
   * try/catch around the request. Callers (the refund/adjustment flow)
   * are expected to handle the rejection and show the user an explicit
   * error rather than silently pretending the adjustment went through.
   */
  async adjust(adjustment: AuthorizationAdjustment): Promise<AdjustmentResult> {
    const issues = validateAdjustment(adjustment);
    if (issues.length > 0) {
      throw new Error(`invalid adjustment: ${issues.join(', ')}`);
    }
    const result = await sendRequest<any>(
      `${this.authorizationsUrl}/${adjustment.authorizationId}`,
      { ...adjustmentRequestConfig, body: adjustment },
    );
    return normalizeAdjustmentResult(result.data);
  }

  /**
   * Check whether an adjustment payload passes local validation without
   * submitting it, used by the refund form's inline validation.
   */
  checkAdjustment(adjustment: AuthorizationAdjustment): string[] {
    return validateAdjustment(adjustment);
  }

  /**
   * Sum the net change in authorized amount across a batch of pending
   * adjustments, used to preview the total impact before confirming.
   */
  sumPendingDelta(adjustments: AuthorizationAdjustment[], currentAmounts: Record<string, number>): number {
    return adjustments.reduce((total, adj) => {
      const current = currentAmounts[adj.authorizationId] ?? 0;
      return total + (adj.newAmountCents - current);
    }, 0);
  }

  /**
   * Format a short label describing an adjustment result, used in the
   * finance team's audit log.
   */
  formatAuditLine(result: AdjustmentResult): string {
    return `auth ${result.authorizationId} adjusted to ${result.amountCents}c at ${result.appliedAt}`;
  }

  /**
   * Find the largest single adjustment in a batch by absolute amount,
   * used by the finance team's anomaly-review flag.
   */
  findLargestAdjustment(adjustments: AuthorizationAdjustment[]): AuthorizationAdjustment | undefined {
    return [...adjustments].sort((a, b) => b.newAmountCents - a.newAmountCents)[0];
  }

  /**
   * Group a batch of adjustments by their reason string, used by the
   * finance team's root-cause breakdown report.
   */
  groupByReason(adjustments: AuthorizationAdjustment[]): Record<string, AuthorizationAdjustment[]> {
    const groups: Record<string, AuthorizationAdjustment[]> = {};
    for (const adjustment of adjustments) {
      if (!groups[adjustment.reason]) {
        groups[adjustment.reason] = [];
      }
      groups[adjustment.reason].push(adjustment);
    }
    return groups;
  }
}

export const defaultAuthorizationAdjustmentClient = new AuthorizationAdjustmentClient();

/**
 * Build a short diagnostic string summarizing a batch of adjustment
 * results, used in the finance ops dashboard's daily digest.
 */
export function summarizeAdjustmentResults(results: AdjustmentResult[]): string {
  const total = results.reduce((sum, result) => sum + result.amountCents, 0);
  return `${results.length} adjustments, net ${total}c`;
}

