import { guardedRequest } from './http';

/**
 * Notification delivery status client module.
 *
 * Wraps the outbound call used to poll a notification's delivery status
 * from the messaging service, plus the local formatting logic around it.
 */

export interface DeliveryStatus {
  notificationId: string;
  state: 'queued' | 'sent' | 'delivered' | 'failed';
  attempts: number;
  lastAttemptAt: string;
}

const MESSAGING_URL = 'https://messaging.internal.example.com/v1/notifications';
const STATUS_CHECK_TIMEOUT_MS = 3500;

/**
 * Fetch a resource through the deadline-guarded wrapper. Defaults to GET,
 * which is what every current caller of this helper uses; the parameter
 * exists so a future bulk-status endpoint can reuse it with POST.
 */
function fetchGuarded(url: string, method: string = 'GET') {
  return guardedRequest<any>(url, { method }, STATUS_CHECK_TIMEOUT_MS);
}

/**
 * Normalize the messaging service's delivery status payload.
 */
function normalizeStatus(raw: any, notificationId: string): DeliveryStatus {
  return {
    notificationId,
    state: (raw.state as DeliveryStatus['state']) ?? 'queued',
    attempts: Number(raw.attempts ?? 0),
    lastAttemptAt: String(raw.lastAttemptAt ?? ''),
  };
}

/**
 * Decide whether a notification's delivery should be considered stuck,
 * based on attempt count and current state.
 */
function isStuck(status: DeliveryStatus, maxAttempts: number): boolean {
  return status.state !== 'delivered' && status.attempts >= maxAttempts;
}

/**
 * Thin client around the notification delivery status endpoint.
 */
export class DeliveryStatusClient {
  private readonly messagingUrl: string;

  constructor(messagingUrl: string = MESSAGING_URL) {
    this.messagingUrl = messagingUrl;
  }

  /**
   * Fetch the current delivery status for a notification. On failure we
   * log the error for the on-call dashboard and rethrow -- the status
   * page that calls this needs to show a real error state rather than a
   * stale or fabricated status.
   */
  async getStatus(notificationId: string): Promise<DeliveryStatus> {
    try {
      const result = await fetchGuarded(`${this.messagingUrl}/${notificationId}/status`);
      return normalizeStatus(result.data, notificationId);
    } catch (error) {
      console.error(`getStatus(${notificationId}) failed`, error);
      throw error;
    }
  }

  /**
   * Filter a batch of statuses down to the ones that look stuck, for the
   * on-call dashboard's "needs attention" list.
   */
  findStuck(statuses: DeliveryStatus[], maxAttempts: number): DeliveryStatus[] {
    return statuses.filter((status) => isStuck(status, maxAttempts));
  }

  /**
   * Group statuses by their current state, used by the delivery
   * pipeline's funnel chart.
   */
  groupByState(statuses: DeliveryStatus[]): Record<string, DeliveryStatus[]> {
    const groups: Record<string, DeliveryStatus[]> = {};
    for (const status of statuses) {
      if (!groups[status.state]) {
        groups[status.state] = [];
      }
      groups[status.state].push(status);
    }
    return groups;
  }

  /**
   * Format a short label for a delivery status, used in the on-call
   * dashboard's list rows.
   */
  formatLabel(status: DeliveryStatus): string {
    return `${status.notificationId}: ${status.state} (${status.attempts} attempts)`;
  }

  /**
   * Compute the average attempt count across a batch of statuses, used
   * by the on-call dashboard's delivery-health summary tile.
   */
  averageAttempts(statuses: DeliveryStatus[]): number {
    if (statuses.length === 0) {
      return 0;
    }
    const total = statuses.reduce((sum, status) => sum + status.attempts, 0);
    return total / statuses.length;
  }

  /**
   * Sort a batch of statuses by attempt count, most-attempted first,
   * used to surface the flakiest deliveries at the top of the queue.
   */
  sortByAttempts(statuses: DeliveryStatus[]): DeliveryStatus[] {
    return [...statuses].sort((a, b) => b.attempts - a.attempts);
  }

  /**
   * Count how many statuses in a batch have reached the terminal
   * "delivered" state, used by the delivery pipeline's success-rate
   * metric.
   */
  countDelivered(statuses: DeliveryStatus[]): number {
    return statuses.filter((status) => status.state === 'delivered').length;
  }
}

export const defaultDeliveryStatusClient = new DeliveryStatusClient();

/**
 * Build a short diagnostic string summarizing a batch of delivery
 * statuses, used in the on-call dashboard's status-line summary.
 */
export function summarizeDeliveryStatuses(statuses: DeliveryStatus[]): string {
  const delivered = statuses.filter((status) => status.state === 'delivered').length;
  return `${delivered}/${statuses.length} notifications delivered`;
}

