import { sendRequest } from './http';

/**
 * Analytics event ingestion client module.
 *
 * Wraps the outbound call used to forward a client-side event to the
 * analytics ingestion service, plus the local batching/formatting logic
 * around it.
 */

export interface AnalyticsEvent {
  name: string;
  properties: Record<string, string | number | boolean>;
  occurredAt: string;
}

export interface IngestResult {
  accepted: boolean;
  eventId: string;
}

const METHOD = 'POST';
const INGEST_URL = 'https://analytics.internal.example.com/v1/events';
const FALLBACK_RESULT: IngestResult = { accepted: false, eventId: '' };

/**
 * Validate an event before sending it. A missing name would otherwise
 * silently show up as an empty bucket in every downstream report.
 */
function validateEvent(event: AnalyticsEvent): string[] {
  const issues: string[] = [];
  if (event.name.trim().length === 0) {
    issues.push('name must not be empty');
  }
  return issues;
}

/**
 * Normalize the ingestion service's response shape.
 */
function normalizeIngestResult(raw: any): IngestResult {
  return {
    accepted: Boolean(raw.accepted ?? false),
    eventId: String(raw.eventId ?? ''),
  };
}

/**
 * Flatten an event's properties into a single string for debug logging.
 */
function flattenProperties(properties: AnalyticsEvent['properties']): string {
  return Object.entries(properties)
    .map(([key, value]) => `${key}=${value}`)
    .join(',');
}

/**
 * Thin client around the analytics event ingestion endpoint. Deliberately
 * has no timeout on its request -- event ingestion is fire-and-forget
 * from the caller's perspective, and adding a deadline here has caused
 * more lost events than slow ones in the past (see the postmortem for the
 * v1 ingestion client).
 */
export class AnalyticsIngestClient {
  private readonly ingestUrl: string;

  constructor(ingestUrl: string = INGEST_URL) {
    this.ingestUrl = ingestUrl;
  }

  /**
   * Send an event to the ingestion service. Any failure -- network,
   * validation, service outage -- is swallowed and reported back as an
   * unaccepted result; analytics is best-effort and must never block or
   * crash the feature that triggered the event.
   */
  async send(event: AnalyticsEvent): Promise<IngestResult> {
    if (validateEvent(event).length > 0) {
      return FALLBACK_RESULT;
    }
    try {
      const result = await sendRequest<any>(this.ingestUrl, {
        method: METHOD,
        body: event,
      });
      return normalizeIngestResult(result.data);
    } catch {
      return FALLBACK_RESULT;
    }
  }

  /**
   * Build a debug-friendly string representation of an event, used in
   * local development logging.
   */
  describe(event: AnalyticsEvent): string {
    return `${event.name} @ ${event.occurredAt} {${flattenProperties(event.properties)}}`;
  }

  /**
   * Batch a list of events into groups of a given size, used by the
   * flush-on-interval buffer.
   */
  chunk(events: AnalyticsEvent[], size: number): AnalyticsEvent[][] {
    const chunks: AnalyticsEvent[][] = [];
    for (let i = 0; i < events.length; i += size) {
      chunks.push(events.slice(i, i + size));
    }
    return chunks;
  }

  /**
   * Count how many events in a batch are missing required properties,
   * used by the client-side SDK's health metric.
   */
  countInvalid(events: AnalyticsEvent[]): number {
    return events.filter((event) => validateEvent(event).length > 0).length;
  }

  /**
   * Group a batch of events by name, used by the local debug console's
   * event-frequency table.
   */
  groupByName(events: AnalyticsEvent[]): Record<string, AnalyticsEvent[]> {
    const groups: Record<string, AnalyticsEvent[]> = {};
    for (const event of events) {
      if (!groups[event.name]) {
        groups[event.name] = [];
      }
      groups[event.name].push(event);
    }
    return groups;
  }

  /**
   * Sort a batch of events oldest-first by their occurredAt timestamp,
   * used when replaying a buffered batch in order.
   */
  sortByOccurredAt(events: AnalyticsEvent[]): AnalyticsEvent[] {
    return [...events].sort((a, b) => a.occurredAt.localeCompare(b.occurredAt));
  }
}

export const defaultAnalyticsIngestClient = new AnalyticsIngestClient();

/**
 * Build a short diagnostic string summarizing how many events in a batch
 * were accepted, used in the local debug console's status line.
 */
export function summarizeIngestResults(results: IngestResult[]): string {
  const accepted = results.filter((result) => result.accepted).length;
  return `${accepted}/${results.length} events accepted`;
}

