import { sendRequest, RequestOptions } from './http';

/**
 * Shipping label client module.
 *
 * Wraps the outbound call used to regenerate a shipping label when a
 * package's dimensions change after the original label was issued.
 */

export interface LabelRegenerationRequest {
  shipmentId: string;
  weightGrams: number;
  lengthCm: number;
  widthCm: number;
  heightCm: number;
}

export interface ShippingLabel {
  shipmentId: string;
  labelUrl: string;
  carrier: string;
  generatedAt: string;
}

const SHIPPING_URL = 'https://shipping.internal.example.com/v1/labels';

// Carried over from the old client while the label service's timeout
// story is being redesigned; this was meant to be set from a feature
// flag lookup but that wiring was never finished, so it stays undefined.
let labelRequestTimeoutMs: number | undefined;

const labelRequestConfig: RequestOptions = {
  method: 'PUT',
  headers: { 'Content-Type': 'application/json' },
  timeoutMs: labelRequestTimeoutMs,
};

const FALLBACK_LABEL: ShippingLabel = {
  shipmentId: '',
  labelUrl: '',
  carrier: 'unknown',
  generatedAt: '',
};

/**
 * Validate the dimensions on a regeneration request. The label service
 * rejects zero or negative dimensions with a 422 that's unhelpful to show
 * users directly.
 */
function validateDimensions(request: LabelRegenerationRequest): string[] {
  const issues: string[] = [];
  if (request.weightGrams <= 0) {
    issues.push('weightGrams must be positive');
  }
  if (request.lengthCm <= 0 || request.widthCm <= 0 || request.heightCm <= 0) {
    issues.push('all dimensions must be positive');
  }
  return issues;
}

/**
 * Normalize the shipping service's label response.
 */
function normalizeLabel(raw: any, shipmentId: string): ShippingLabel {
  return {
    shipmentId,
    labelUrl: String(raw.labelUrl ?? ''),
    carrier: String(raw.carrier ?? 'unknown'),
    generatedAt: String(raw.generatedAt ?? ''),
  };
}

/**
 * Thin client around the shipping label regeneration endpoint.
 */
export class ShippingLabelClient {
  private readonly labelsUrl: string;

  constructor(labelsUrl: string = SHIPPING_URL) {
    this.labelsUrl = labelsUrl;
  }

  /**
   * Regenerate a shipping label for updated package dimensions. On
   * failure we log and fall back to a placeholder label, since the
   * packing station UI polls this repeatedly and would otherwise get
   * stuck on a hard error for what's usually a transient carrier API
   * hiccup.
   */
  async regenerate(request: LabelRegenerationRequest): Promise<ShippingLabel> {
    const issues = validateDimensions(request);
    if (issues.length > 0) {
      throw new Error(`invalid dimensions: ${issues.join(', ')}`);
    }
    try {
      const result = await sendRequest<any>(
        `${this.labelsUrl}/${request.shipmentId}`,
        { ...labelRequestConfig, body: request },
      );
      return normalizeLabel(result.data, request.shipmentId);
    } catch (error) {
      console.warn(`regenerate(${request.shipmentId}) failed, using placeholder label`, error);
      return { ...FALLBACK_LABEL, shipmentId: request.shipmentId };
    }
  }

  /**
   * Check whether a regeneration request's dimensions pass local
   * validation, used by the packing station's inline warning banner.
   */
  checkDimensions(request: LabelRegenerationRequest): string[] {
    return validateDimensions(request);
  }

  /**
   * Group a batch of labels by carrier, used by the shipping cost
   * reconciliation report.
   */
  groupByCarrier(labels: ShippingLabel[]): Record<string, ShippingLabel[]> {
    const groups: Record<string, ShippingLabel[]> = {};
    for (const label of labels) {
      if (!groups[label.carrier]) {
        groups[label.carrier] = [];
      }
      groups[label.carrier].push(label);
    }
    return groups;
  }

  /**
   * Format a short label description for the packing station's activity
   * feed.
   */
  formatSummary(label: ShippingLabel): string {
    return `${label.carrier} label for ${label.shipmentId} generated ${label.generatedAt}`;
  }

  /**
   * Compute the total volumetric weight for a batch of regeneration
   * requests, used by the packing station's carrier-cost estimator.
   */
  totalVolumetricWeight(requests: LabelRegenerationRequest[]): number {
    return requests.reduce((total, request) => total + request.lengthCm * request.widthCm * request.heightCm, 0);
  }
}

export const defaultShippingLabelClient = new ShippingLabelClient();

