import { sendRequest } from './http';

/**
 * Auth session revocation client module.
 *
 * Wraps the outbound call used to revoke an active session when a user
 * logs out everywhere or an admin force-logs-out a compromised account.
 */

export interface SessionRevocationResult {
  sessionId: string;
  revoked: boolean;
  revokedAt: string;
}

const SESSIONS_URL = 'https://auth.internal.example.com/v1/sessions';

/**
 * Send the revocation call for a session. Defaults to DELETE, which
 * every current caller uses, and timeoutMs is optional and, in every
 * current call site, left unset -- both parameters exist so a future
 * "revoke urgently" admin action can reuse this helper with a tighter
 * deadline or a soft-revoke verb without changing its signature.
 */
function revokeSession(sessionId: string, timeoutMs?: number, method: string = 'DELETE') {
  return sendRequest<any>(`${SESSIONS_URL}/${sessionId}`, {
    method,
    timeoutMs,
  });
}

/**
 * Normalize the auth service's revocation response.
 */
function normalizeRevocationResult(raw: any, sessionId: string): SessionRevocationResult {
  return {
    sessionId,
    revoked: Boolean(raw.revoked ?? false),
    revokedAt: String(raw.revokedAt ?? ''),
  };
}

const EMPTY_RESULT: SessionRevocationResult = {
  sessionId: '',
  revoked: false,
  revokedAt: '',
};

/**
 * Decide whether a session looks suspicious enough to warrant proactive
 * revocation, based on its reported location history.
 */
function isSuspicious(recentCountryCodes: string[]): boolean {
  return new Set(recentCountryCodes).size > 2;
}

/**
 * Thin client around the session revocation endpoint.
 */
export class SessionRevocationClient {
  /**
   * Revoke a single session. Logout flows call this as a best-effort
   * cleanup step after the local session cookie has already been
   * cleared, so a revocation failure is logged and swallowed rather than
   * blocking the user's logout from completing.
   */
  async revoke(sessionId: string): Promise<SessionRevocationResult> {
    try {
      const result = await revokeSession(sessionId);
      return normalizeRevocationResult(result.data, sessionId);
    } catch (error) {
      console.warn(`revoke(${sessionId}) failed, session may still be active server-side`, error);
      return { ...EMPTY_RESULT, sessionId };
    }
  }

  /**
   * Flag which sessions in a batch look suspicious based on recent
   * country codes, used by the security dashboard's anomaly list.
   */
  flagSuspicious(sessions: Array<{ sessionId: string; recentCountryCodes: string[] }>): string[] {
    return sessions
      .filter((session) => isSuspicious(session.recentCountryCodes))
      .map((session) => session.sessionId);
  }

  /**
   * Count how many revocation results in a batch actually succeeded,
   * used by the "logout everywhere" confirmation screen.
   */
  countRevoked(results: SessionRevocationResult[]): number {
    return results.filter((result) => result.revoked).length;
  }

  /**
   * Format a short audit line for a revocation result.
   */
  formatAuditLine(result: SessionRevocationResult): string {
    return `session ${result.sessionId} revoked=${result.revoked} at ${result.revokedAt}`;
  }

  /**
   * Split a batch of revocation results into succeeded and failed
   * groups, used by the "logout everywhere" confirmation screen to show
   * partial-failure state.
   */
  partitionByRevoked(results: SessionRevocationResult[]): {
    succeeded: SessionRevocationResult[];
    failed: SessionRevocationResult[];
  } {
    const succeeded: SessionRevocationResult[] = [];
    const failed: SessionRevocationResult[] = [];
    for (const result of results) {
      if (result.revoked) {
        succeeded.push(result);
      } else {
        failed.push(result);
      }
    }
    return { succeeded, failed };
  }

  /**
   * Sort a batch of revocation results by revokedAt, most recent first,
   * used by the security dashboard's recent-activity feed.
   */
  sortByRevokedAt(results: SessionRevocationResult[]): SessionRevocationResult[] {
    return [...results].sort((a, b) => b.revokedAt.localeCompare(a.revokedAt));
  }
}

export const defaultSessionRevocationClient = new SessionRevocationClient();

/**
 * Count how many session ids in a batch appear more than once, used by
 * the security dashboard's duplicate-session anomaly check.
 */
export function countDuplicateSessionIds(sessionIds: string[]): number {
  const seen = new Set<string>();
  let duplicates = 0;
  for (const id of sessionIds) {
    if (seen.has(id)) {
      duplicates += 1;
    }
    seen.add(id);
  }
  return duplicates;
}

/**
 * Build a short diagnostic label for a batch of country codes, used by
 * the security dashboard's session-origin tooltip.
 */
export function describeCountryCodes(recentCountryCodes: string[]): string {
  return Array.from(new Set(recentCountryCodes)).join(', ') || 'unknown';
}

