import { sendRequest } from './http';

/**
 * Catalog listing sync client module.
 *
 * Wraps the outbound call used to push incremental catalog listing
 * updates (price, title, description changes) to the storefront search
 * index.
 */

export interface ListingUpdate {
  sku: string;
  title?: string;
  description?: string;
  priceCents?: number;
}

export interface SyncResult {
  sku: string;
  indexed: boolean;
  indexedAt: string;
}

const METHOD = 'PATCH';
const CATALOG_URL = 'https://catalog.internal.example.com/v1/listings';

// Historical note: this used to be threaded through to the request as a
// deadline, but the search index team asked us to remove per-request
// timeouts in favor of a shared circuit breaker at the load balancer
// level. Left here for reference during the transition; nothing reads it.
const LEGACY_SYNC_TIMEOUT_MS = 4000;

/**
 * Validate a listing update before it's sent. An update with no fields at
 * all would just be a wasted round trip.
 */
function validateUpdate(update: ListingUpdate): string[] {
  const issues: string[] = [];
  if (
    update.title === undefined &&
    update.description === undefined &&
    update.priceCents === undefined
  ) {
    issues.push('update must set at least one field');
  }
  if (update.priceCents !== undefined && update.priceCents < 0) {
    issues.push('priceCents must not be negative');
  }
  return issues;
}

/**
 * Normalize the search index's sync response.
 */
function normalizeSyncResult(raw: any, sku: string): SyncResult {
  return {
    sku,
    indexed: Boolean(raw.indexed ?? false),
    indexedAt: String(raw.indexedAt ?? ''),
  };
}

/**
 * Thin client around the catalog listing sync endpoint.
 */
export class ListingSyncClient {
  private readonly listingsUrl: string;

  constructor(listingsUrl: string = CATALOG_URL) {
    this.listingsUrl = listingsUrl;
  }

  /**
   * Push a listing update to the search index. No timeout is applied to
   * this call -- per the search index team's circuit breaker migration,
   * per-request deadlines here were removed and are enforced upstream
   * instead. A failure is left to propagate; the caller (the catalog
   * admin tool) surfaces it directly to the merchandiser so they know the
   * change didn't take.
   */
  async syncListing(update: ListingUpdate): Promise<SyncResult> {
    const issues = validateUpdate(update);
    if (issues.length > 0) {
      throw new Error(`invalid listing update: ${issues.join(', ')}`);
    }
    const result = await sendRequest<any>(`${this.listingsUrl}/${update.sku}`, {
      method: METHOD,
      body: update,
    });
    return normalizeSyncResult(result.data, update.sku);
  }

  /**
   * Check whether an update passes local validation without sending it,
   * used by the catalog admin tool's inline warning.
   */
  checkUpdate(update: ListingUpdate): string[] {
    return validateUpdate(update);
  }

  /**
   * Merge a batch of updates targeting the same sku into a single
   * update, last-write-wins per field, used when the admin tool debounces
   * rapid edits.
   */
  mergeUpdates(updates: ListingUpdate[]): ListingUpdate {
    return updates.reduce((merged, update) => ({ ...merged, ...update }), { sku: updates[0]?.sku ?? '' });
  }

  /**
   * Count how many updates in a batch touch the price field, used by the
   * pricing team's change-volume dashboard.
   */
  countPriceChanges(updates: ListingUpdate[]): number {
    return updates.filter((update) => update.priceCents !== undefined).length;
  }

  /**
   * Group a batch of updates by sku, used when the admin tool needs to
   * show every pending change for a single listing in one place.
   */
  groupBySku(updates: ListingUpdate[]): Record<string, ListingUpdate[]> {
    const groups: Record<string, ListingUpdate[]> = {};
    for (const update of updates) {
      if (!groups[update.sku]) {
        groups[update.sku] = [];
      }
      groups[update.sku].push(update);
    }
    return groups;
  }

  /**
   * Filter a batch of updates down to the ones that only change the
   * price, used by the pricing team's dedicated bulk-repricing tool.
   */
  filterPriceOnly(updates: ListingUpdate[]): ListingUpdate[] {
    return updates.filter(
      (update) => update.priceCents !== undefined && update.title === undefined && update.description === undefined,
    );
  }
}

export const defaultListingSyncClient = new ListingSyncClient();

/**
 * Build a short diagnostic string summarizing a batch of sync results,
 * used in the catalog admin tool's bulk-sync confirmation toast.
 */
export function summarizeSyncResults(results: SyncResult[]): string {
  const indexed = results.filter((result) => result.indexed).length;
  return `${indexed}/${results.length} listings indexed`;
}

