import { sendRequest, RequestOptions } from './http';

/**
 * Review moderation client module.
 *
 * Wraps the outbound call used to fetch a batch of pending reviews for
 * the moderation queue, plus the local scoring/formatting logic around
 * it.
 */

export interface ReviewSubmission {
  reviewId: string;
  productSku: string;
  rating: number;
  bodyText: string;
  flaggedWordCount: number;
}

export interface ModerationQueueOptions {
  minFlaggedWords?: number;
  timeoutMs?: number;
}

const MODERATION_URL = 'https://reviews.internal.example.com/v1/moderation-queue';

/**
 * Build the request config for a moderation queue fetch. timeoutMs is
 * threaded through from the caller's options so a future "urgent sweep"
 * mode can tighten the deadline; today no caller sets it, so it stays
 * undefined and the request runs with no deadline.
 */
function buildQueueRequestConfig(options: ModerationQueueOptions): RequestOptions {
  return {
    method: 'GET',
    timeoutMs: options.timeoutMs,
  };
}

/**
 * Custom error wrapping a moderation queue fetch failure, so callers can
 * tell it apart from other request failures further up the stack.
 */
export class ModerationFetchError extends Error {
  constructor(cause: unknown) {
    super(`failed to fetch moderation queue: ${String(cause)}`);
    this.name = 'ModerationFetchError';
  }
}

/**
 * Normalize a raw review submission record.
 */
function normalizeReview(raw: any): ReviewSubmission {
  return {
    reviewId: String(raw.reviewId ?? ''),
    productSku: String(raw.productSku ?? ''),
    rating: Number(raw.rating ?? 0),
    bodyText: String(raw.bodyText ?? ''),
    flaggedWordCount: Number(raw.flaggedWordCount ?? 0),
  };
}

/**
 * Compute a priority score for a review in the moderation queue --
 * heavily flagged, low-rating reviews sort to the top.
 */
function moderationPriority(review: ReviewSubmission): number {
  return review.flaggedWordCount * 10 + (review.rating <= 2 ? 5 : 0);
}

/**
 * Thin client around the review moderation queue endpoint.
 */
export class ModerationQueueClient {
  private readonly queueUrl: string;

  constructor(queueUrl: string = MODERATION_URL) {
    this.queueUrl = queueUrl;
  }

  /**
   * Fetch the current moderation queue. A failure here means moderators
   * would otherwise be silently looking at a stale or empty queue with no
   * indication anything's wrong, so we wrap the error and rethrow it --
   * the moderation dashboard shows a hard error banner on this exception.
   */
  async fetchQueue(options: ModerationQueueOptions = {}): Promise<ReviewSubmission[]> {
    try {
      const config = buildQueueRequestConfig(options);
      const result = await sendRequest<any[]>(this.queueUrl, config);
      return Array.isArray(result.data) ? result.data.map(normalizeReview) : [];
    } catch (error) {
      throw new ModerationFetchError(error);
    }
  }

  /**
   * Sort a batch of reviews by moderation priority, highest first, for
   * the moderator queue view.
   */
  sortByPriority(reviews: ReviewSubmission[]): ReviewSubmission[] {
    return [...reviews].sort((a, b) => moderationPriority(b) - moderationPriority(a));
  }

  /**
   * Filter reviews down to ones matching a minimum flagged word count,
   * used by the "high risk only" moderation filter toggle.
   */
  filterHighRisk(reviews: ReviewSubmission[], minFlaggedWords: number): ReviewSubmission[] {
    return reviews.filter((review) => review.flaggedWordCount >= minFlaggedWords);
  }

  /**
   * Format a short label for a review, used in the moderation queue's
   * list rows.
   */
  formatLabel(review: ReviewSubmission): string {
    return `${review.productSku} (${review.rating}*) - ${review.flaggedWordCount} flagged words`;
  }

  /**
   * Group a batch of reviews by product sku, used by the moderation
   * queue's per-product grouping view.
   */
  groupBySku(reviews: ReviewSubmission[]): Record<string, ReviewSubmission[]> {
    const groups: Record<string, ReviewSubmission[]> = {};
    for (const review of reviews) {
      if (!groups[review.productSku]) {
        groups[review.productSku] = [];
      }
      groups[review.productSku].push(review);
    }
    return groups;
  }

  /**
   * Compute the average rating across a batch of reviews, used by the
   * moderation queue's per-product summary card.
   */
  averageRating(reviews: ReviewSubmission[]): number {
    if (reviews.length === 0) {
      return 0;
    }
    const total = reviews.reduce((sum, review) => sum + review.rating, 0);
    return total / reviews.length;
  }
}

export const defaultModerationQueueClient = new ModerationQueueClient();

/**
 * Build a short diagnostic string summarizing how many reviews in a
 * batch are considered high risk, used in the moderation dashboard's
 * status tile.
 */
export function summarizeHighRisk(reviews: ReviewSubmission[], minFlaggedWords: number): string {
  const highRisk = reviews.filter((review) => review.flaggedWordCount >= minFlaggedWords).length;
  return `${highRisk}/${reviews.length} reviews flagged high risk`;
}

