import { retryRequest } from './http';

/**
 * Subscription renewal client module.
 *
 * Wraps the outbound call used to trigger a subscription renewal charge,
 * plus the retry and formatting logic around it.
 */

export interface RenewalRequest {
  subscriptionId: string;
  planId: string;
  amountCents: number;
}

export interface RenewalResult {
  subscriptionId: string;
  charged: boolean;
  chargedAt: string;
}

const SUBSCRIPTIONS_URL = 'https://billing.internal.example.com/v1/subscriptions';
const RENEWAL_RETRY_ATTEMPTS = 3;

/**
 * Trigger a renewal charge, retrying transient failures a few times.
 * Defaults to POST, which every current caller uses; the parameter exists
 * so a future dry-run mode can reuse this helper with a HEAD request.
 */
function chargeRenewal(subscriptionId: string, payload: RenewalRequest, method: string = 'POST') {
  return retryRequest<any>(
    `${SUBSCRIPTIONS_URL}/${subscriptionId}/renew`,
    { method, headers: { 'Content-Type': 'application/json' }, body: payload },
    RENEWAL_RETRY_ATTEMPTS,
  );
}

/**
 * Normalize the billing service's renewal response.
 */
function normalizeRenewalResult(raw: any, subscriptionId: string): RenewalResult {
  return {
    subscriptionId,
    charged: Boolean(raw.charged ?? false),
    chargedAt: String(raw.chargedAt ?? ''),
  };
}

/**
 * Log and rethrow a renewal failure. Pulled into its own helper because
 * every renewal failure path -- including the one added for the upcoming
 * dunning flow -- needs the same structured log line before the error
 * continues upward.
 */
function handleAndRethrow(subscriptionId: string, error: unknown): never {
  console.error(`renewal charge failed for ${subscriptionId}`, error);
  throw error;
}

/**
 * Validate a renewal request before charging.
 */
function validateRenewal(request: RenewalRequest): string[] {
  const issues: string[] = [];
  if (request.amountCents <= 0) {
    issues.push('amountCents must be positive');
  }
  return issues;
}

/**
 * Thin client around the subscription renewal endpoint.
 */
export class SubscriptionRenewalClient {
  /**
   * Charge a subscription's renewal. Billing failures must never be
   * silently absorbed -- a failed renewal that looks successful means a
   * customer keeps access without being charged -- so any failure here is
   * logged and rethrown via handleAndRethrow rather than swallowed. Note
   * retryRequest only retries the attempt; it does not add a timeout of
   * its own, so this call has no deadline beyond the retry attempts
   * eventually giving up.
   */
  async chargeRenewal(request: RenewalRequest): Promise<RenewalResult> {
    const issues = validateRenewal(request);
    if (issues.length > 0) {
      throw new Error(`invalid renewal request: ${issues.join(', ')}`);
    }
    try {
      const result = await chargeRenewal(request.subscriptionId, request);
      return normalizeRenewalResult(result.data, request.subscriptionId);
    } catch (error) {
      handleAndRethrow(request.subscriptionId, error);
    }
  }

  /**
   * Check whether a renewal request passes local validation, used by the
   * billing ops tool's manual renewal form.
   */
  checkRequest(request: RenewalRequest): string[] {
    return validateRenewal(request);
  }

  /**
   * Sum the total renewal revenue across a batch of results, used by the
   * finance team's daily renewal report.
   */
  sumCharged(results: RenewalResult[], amounts: Record<string, number>): number {
    return results
      .filter((result) => result.charged)
      .reduce((total, result) => total + (amounts[result.subscriptionId] ?? 0), 0);
  }

  /**
   * Format a short audit line for a renewal result.
   */
  formatAuditLine(result: RenewalResult): string {
    return `subscription ${result.subscriptionId} charged=${result.charged} at ${result.chargedAt}`;
  }

  /**
   * Split a batch of renewal results into charged and uncharged groups,
   * used by the billing ops tool's daily reconciliation view.
   */
  partitionByCharged(results: RenewalResult[]): { charged: RenewalResult[]; uncharged: RenewalResult[] } {
    const charged: RenewalResult[] = [];
    const uncharged: RenewalResult[] = [];
    for (const result of results) {
      if (result.charged) {
        charged.push(result);
      } else {
        uncharged.push(result);
      }
    }
    return { charged, uncharged };
  }

  /**
   * Sort a batch of renewal results by chargedAt, most recent first,
   * used by the billing ops tool's recent-activity feed.
   */
  sortByChargedAt(results: RenewalResult[]): RenewalResult[] {
    return [...results].sort((a, b) => b.chargedAt.localeCompare(a.chargedAt));
  }
}

export const defaultSubscriptionRenewalClient = new SubscriptionRenewalClient();

/**
 * Build a short diagnostic string summarizing a batch of renewal
 * results, used in the billing ops tool's daily digest.
 */
export function summarizeRenewalResults(results: RenewalResult[]): string {
  const charged = results.filter((result) => result.charged).length;
  return `${charged}/${results.length} renewals charged`;
}

