export function retryRequest(fn: () => Promise<any>, attempts: number, backoffMs: number): Promise<any> {
  // new signature: retries `fn` up to `attempts` times, waiting `backoffMs` between attempts
  let lastError: unknown;
  return (async () => {
    for (let i = 0; i < attempts; i++) {
      try {
        return await fn();
      } catch (e) {
        lastError = e;
        await new Promise((resolve) => setTimeout(resolve, backoffMs));
      }
    }
    throw lastError;
  })();
}

